corrected_code:
import { json, ActionFunctionArgs } from '@remix-run/node';
import { pool } from '~/pg.server';
import { requireAuth } from '~/auth.server';

export async function action({ request, params }: ActionFunctionArgs) {
  const user = await requireAuth(request);

  const result = await pool.query(
    "UPDATE user_alerts SET is_dismissed = true WHERE id = $1 AND user_id = $2 RETURNING id",
    [params.alertId, user.id]
  );
  if (!result.rows.length) {
    return json({ error: 'Alert not found or unauthorized' }, { status: 403 });
  }

  return json({ dismissed: true, alertId: params.alertId });
}
